import org.jetbrains.kotlin.gradle.dsl.JvmTarget
import org.jetbrains.kotlin.gradle.plugin.mpp.KotlinNativeTarget

// The Rust core for Kotlin: `CoreBridge` in commonMain (generated by
// shared/wiregen from the core's op table) with its two implementations, JNI
// on the JVM (`JniCore`, which :lollo's Android code runs on) and the C ABI
// (shared/include/lollo.h) through cinterop on Kotlin/Native (`NativeCore`).
// linuxX64 exists only to run the bridge tests on a Linux host; the iOS
// targets compile and link on macOS only (CI job `bridge-macos`). See
// ios/README.md.
plugins {
    id("org.jetbrains.kotlin.multiplatform")
    id("org.jetbrains.kotlin.plugin.serialization")
}

val repoRoot: File = rootDir.parentFile

kotlin {
    jvm {
        compilerOptions { jvmTarget.set(JvmTarget.fromTarget(libs.versions.jvm.target.get())) }
    }
    linuxX64()
    iosArm64()
    iosSimulatorArm64()

    targets.withType<KotlinNativeTarget>().configureEach {
        compilations.getByName("main").cinterops.create("lollo") {
            definitionFile.set(project.file("src/nativeInterop/cinterop/lollo.def"))
            includeDirs(File(repoRoot, "shared/include"))
            // Declare the test hooks on every target; only test binaries call
            // them, and only those link the hook-enabled library.
            compilerOpts("-DLOLLO_TEST_HOOKS")
        }
        binaries.all { rustCore.link(this@configureEach, this) }
    }

    sourceSets {
        commonTest {
            kotlin.srcDir(repoRootConstant("app.milestone.core"))
            dependencies {
                implementation(kotlin("test"))
                implementation(libs.kotlinx.serialization.json)
            }
        }
    }
}
